# Renders docs/wardrobe/COVERAGE.md and docs/wardrobe/missing-art.json from docs/wardrobe/coverage.json
# (written by: python3 tests/wardrobe-smoke/run.py Shardfall_vX.html --write-coverage) and the wardrobe data in the build.
# usage: python3 tools/wardrobe_report.py Shardfall_v0.31.html
import json, os, re, subprocess, sys
root = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); build = sys.argv[1]
cov = json.load(open(os.path.join(root, 'docs/wardrobe/coverage.json')))
js = r"""
const fs = require('fs'); const html = fs.readFileSync(process.argv[1], 'utf8'); const sc = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map(m => m[1]);
const g = {}, m = { exports: {} }; new Function('module', 'globalThis', sc.find(t => t.includes('SF.METALS')))(m, g); g.SF = m.exports;
for (const k of ['SF.MAGERY = MG', 'SF.EQ = EQ', 'SF.WARDROBE = W', '.RIG = RIG']) new Function('module', 'globalThis', sc.find(t => t.includes(k)))({}, g);
const W = g.SF.WARDROBE; console.log(JSON.stringify({ OVERLAYS: W.OVERLAYS, PROPS: W.PROPS, ROLES: Object.fromEntries(Object.entries(W.ROLES).map(([k, r]) => [k, { n: r.n, prop: r.prop, overlays: r.overlays.map(o => o[0]) }])),
  HOSTILE: Object.fromEntries(Object.entries(W.HOSTILE).map(([k, h]) => [k, { n: h.n, mapped: Object.keys(W.MOB_ROLE).filter(t => W.MOB_ROLE[t] === k) }])), VERSION: W.VERSION }));
"""
W = json.loads(subprocess.run(['node', '-e', js, os.path.join(root, build)], capture_output=True, text=True, check=True).stdout)
rows = cov['rows']; ppl = [r for r in rows if r['role']]; crea = [r for r in rows if not r['role']]
L = [f"# Wardrobe coverage matrix (generated)\n", f"Build `{cov['build']}`, wardrobe v{W['VERSION']}. Generated by `tools/wardrobe_report.py` from the live game (`tests/wardrobe-smoke/run.py --write-coverage`). Do not edit by hand.\n",
     "Art status for every row: **procedural prototype** (src/humanrig.js). No painted production layer exists yet for any piece. `source` = `equip` means the figure shows the actor's real equipment; `cosmetic` means a preset made of real item ids that is not equipment and never loot.\n",
     f"## People ({len(ppl)})\n", "| Actor id | Game role / profession | Region | Wardrobe role | Rank | Body | Source | Overlays | Work prop | Missing art | Mapped via |", "|---|---|---|---|---|---|---|---|---|---|---|"]
for r in sorted(ppl, key=lambda r: (r['kind'] != 'player', r['kind'], r['region'] or '', r['role'], r['id'])):
  L.append(f"| `{r['id']}` | {r['gameRole'] or '—'} | {r['region'] or '—'} | {r['role']} | {r['rank'] or '—'} | {r['body']} | {r['source']} | {', '.join(r['overlays']) or '—'} | {r['prop'] or '—'} | {', '.join(r['missing']) or '—'} | {r['via']} |")
L += ["", f"## Creatures ({len(crea)} live types) — no wardrobe; their own art is unchanged\n", ', '.join(sorted(r['gameRole'] for r in crea)), "",
      "## Hostile presets\n", "| Preset | Live mob ids mapped |", "|---|---|"]
for k, h in W['HOSTILE'].items(): L.append(f"| {k} ({h['n']}) | {', '.join(h['mapped']) or '**none — no such mob exists; defined for future content, nothing spawned**'} |")
L += ["", "## Civilian roles without a live NPC today\n", ', '.join(sorted(k for k in W['ROLES'] if k not in {r['role'] for r in ppl})) or '—', ""]
open(os.path.join(root, 'docs/wardrobe/COVERAGE.md'), 'w').write('\n'.join(L) + '\n')
miss = {'note': 'Everything the wardrobe can draw today is procedural prototype art. This list is what has NO art at all, then what needs a painted production layer.',
  'no_art': {'overlays': {k: v['n'] for k, v in W['OVERLAYS'].items() if v['status'] == 'missing'}, 'props': {k: v['n'] for k, v in W['PROPS'].items() if v['status'] == 'missing'},
             'used_by_live_npcs': sorted({m for r in ppl for m in r['missing']})},
  'needs_painted_layer': {'overlays': {k: v['n'] for k, v in W['OVERLAYS'].items() if v['status'] == 'procedural'}, 'props': {k: v['n'] for k, v in W['PROPS'].items() if v['status'] == 'procedural'}}}
json.dump(miss, open(os.path.join(root, 'docs/wardrobe/missing-art.json'), 'w'), indent=1)
print('wrote docs/wardrobe/COVERAGE.md and missing-art.json:', len(ppl), 'people,', len(crea), 'creature types')
